//! Replays `fixtures/leader/*.json` (generated by `scripts/gen-leader-fixtures.ts` against the real TS leader)
//! and compares rows after every op.

use livestore_core::{Event, SeqNum};
use livestore_sqlite::{LocalLeader, PulledEvent};
use rusqlite::Connection;
use serde_json::{Map, Value, json};

#[test]
fn leader_fixtures_match_ts() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/leader");
    let mut count = 0;
    for entry in std::fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        let fixture: Value =
            serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        run_fixture(&fixture);
        count += 1;
    }
    assert!(count >= 8, "expected leader fixtures, found {count}");
}

fn run_fixture(fixture: &Value) {
    let name = fixture["name"].as_str().unwrap();
    let mut leader = LocalLeader::open_in_memory(
        livestore_todomvc::schema(),
        fixture["clientId"].as_str().unwrap(),
        fixture["sessionId"].as_str().unwrap(),
    )
    .unwrap();

    for (i, step) in fixture["steps"].as_array().unwrap().iter().enumerate() {
        let op = &step["op"];
        let result = match op["op"].as_str().unwrap() {
            "commit" => leader
                .commit(op["name"].as_str().unwrap(), op["args"].clone())
                .map(|_| ()),
            "pull" => leader
                .apply_upstream(
                    op["events"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(pulled)
                        .collect(),
                )
                .map(|_| ()),
            "rebuild" => leader.rebuild_state(),
            other => panic!("unknown op {other}"),
        };
        let actual_result = if result.is_ok() { "ok" } else { "error" };
        assert_eq!(
            actual_result, step["result"],
            "{name} step {i} result: {result:?}"
        );
        let actual = snapshot(&leader);
        for (key, expected) in step["snapshot"].as_object().unwrap() {
            assert_eq!(
                &actual[key], expected,
                "{name} step {i} ({op}) mismatch in {key}"
            );
        }
    }

    for (db, conn) in [
        ("state", leader.db().state_conn()),
        ("eventlog", leader.db().eventlog_conn()),
    ] {
        let actual = rows(
            conn,
            "SELECT type, name, tbl_name, sql FROM sqlite_master ORDER BY name",
        );
        assert_eq!(actual, fixture["ddl"][db], "{name} ddl {db}");
    }
}

fn pulled(e: &Value) -> PulledEvent {
    let seq = |n: &Value| SeqNum::new(n.as_i64().unwrap(), 0, 0);
    PulledEvent {
        event: Event {
            name: e["name"].as_str().unwrap().into(),
            args: e["args"].clone(),
            seq_num: seq(&e["seqNum"]),
            parent_seq_num: seq(&e["parentSeqNum"]),
            client_id: e["clientId"].as_str().unwrap().into(),
            session_id: e["sessionId"].as_str().unwrap().into(),
        },
        sync_metadata: e.get("metadata").cloned(),
    }
}

fn snapshot(leader: &LocalLeader) -> Value {
    let (s, e) = (leader.db().state_conn(), leader.db().eventlog_conn());
    let sync = leader.sync_state();
    json!({
        "todos": rows(s, "SELECT * FROM todos ORDER BY id"),
        "uiState": rows(s, "SELECT * FROM uiState ORDER BY id"),
        "stateHead": rows(s, "SELECT * FROM __livestore_state_head"),
        "journalKeys": rows(s, "SELECT seqNumGlobal, seqNumClient, seqNumRebaseGeneration, changeset IS NULL AS changesetIsNull FROM __livestore_materialization_journal ORDER BY 1, 2, 3"),
        "rebuildMarker": rows(s, "SELECT * FROM __livestore_rebuild"),
        "eventlog": rows(e, "SELECT seqNumGlobal, seqNumClient, seqNumRebaseGeneration, parentSeqNumGlobal, parentSeqNumClient, parentSeqNumRebaseGeneration, name, argsJson, clientId, sessionId, schemaHash, syncMetadataJson FROM eventlog ORDER BY 1, 2, 3"),
        "syncStatus": rows(e, "SELECT * FROM __livestore_sync_status"),
        "schemaMeta": rows(s, "SELECT tableName, schemaHash FROM __livestore_schema ORDER BY tableName"),
        "eventDefs": rows(s, "SELECT eventName, schemaHash FROM __livestore_schema_event_defs ORDER BY eventName"),
        "syncState": { "pending": sync.pending, "upstreamHead": sync.upstream_head, "localHead": sync.local_head },
    })
}

fn rows(conn: &Connection, sql: &str) -> Value {
    let mut stmt = conn.prepare(sql).unwrap();
    let names: Vec<String> = stmt.column_names().iter().map(|s| s.to_string()).collect();
    let out = stmt
        .query_map([], |row| {
            let mut obj = Map::new();
            for (i, n) in names.iter().enumerate() {
                let v = match row.get_ref(i)? {
                    rusqlite::types::ValueRef::Null => Value::Null,
                    rusqlite::types::ValueRef::Integer(x) => json!(x),
                    rusqlite::types::ValueRef::Real(x) => json!(x),
                    rusqlite::types::ValueRef::Text(t) => json!(String::from_utf8_lossy(t)),
                    rusqlite::types::ValueRef::Blob(_) => panic!("blob in snapshot"),
                };
                obj.insert(n.clone(), v);
            }
            Ok(Value::Object(obj))
        })
        .unwrap()
        .collect::<Result<Vec<_>, _>>()
        .unwrap();
    Value::Array(out)
}
